/**
 * TALK3: WBSY Talk's extra shows, ads and their cast (extra-shows.json, generated by scripts/dev/talk3/build.py).
 * Fetched as their own chunk on hosted and native builds only, so the single-file build carries none of it; added to
 * the schedule's shuffle bag once loaded (`TalkSchedule.addShows`). Same Show shape as the bundled shows.
 */
import type { CastMember, ScriptLine, Show, ShowKind } from '../types';

export interface ExtraShowFile { cast: CastMember[]; shows: Show[]; ads: Show[] }

const KINDS: readonly ShowKind[] = ['callin', 'realestate', 'board', 'wellness', 'latenight', 'interview', 'news', 'ad'];

function shows(v: unknown, ad: boolean): Show[] {
  const out: Show[] = [];
  for (const r of Array.isArray(v) ? v : []) {
    const o = r as Record<string, unknown> | null;
    if (!o || typeof o.id !== 'string' || !Array.isArray(o.lines)) continue;
    const lines = (o.lines as unknown[]).filter((l): l is ScriptLine => !!l && typeof (l as ScriptLine).who === 'string' && typeof (l as ScriptLine).text === 'string');
    if (lines.length === 0) continue;
    const kind = ad ? 'ad' : KINDS.includes(o.kind as ShowKind) ? (o.kind as ShowKind) : 'interview';
    out.push({ id: o.id, title: typeof o.title === 'string' ? o.title : o.id, kind, host: typeof o.host === 'string' ? o.host : lines[0].who, lines });
  }
  return out;
}

export function parseExtraShows(raw: unknown): ExtraShowFile {
  const o = (raw && typeof raw === 'object' ? raw : {}) as Record<string, unknown>;
  const cast = (Array.isArray(o.cast) ? o.cast : []).filter((c): c is CastMember => !!c && typeof (c as CastMember).id === 'string' && !!(c as CastMember).fallback);
  return { cast, shows: shows(o.shows, false), ads: shows(o.ads, true) };
}

export async function loadExtraShows(): Promise<ExtraShowFile | null> {
  if (import.meta.env?.VITE_HOSTED !== '1') return null;
  const mods = import.meta.glob('./extra-shows.json', { import: 'default' }) as Record<string, () => Promise<unknown>>;
  const first = Object.values(mods)[0];
  return first ? parseExtraShows(await first()) : null;
}
